// Terrain for a simulation that runs in the page's own thread, generated by the page's chunk workers:
// a chunk takes about 2 ms to generate, which a frame that also draws cannot spare.
import type { ChunkSource, GenResult } from '../sim/chunksource';
import type { WorkerPool } from '../world/pool';

interface Job { dim: number; cx: number; cz: number; prio: number; n: number; sent: boolean; fails: number }

export class PoolSource implements ChunkSource {
  private jobs = new Map<string, Job>();
  private done: GenResult[] = [];
  private n = 0; private out = 0;

  /** At most `most` jobs are with the workers at once; the rest wait here, where they can still be cancelled or overtaken. */
  constructor(private pool: WorkerPool, public seed: number, private most = Math.max(1, pool.size - 1)) {}

  get pending(): number { return this.jobs.size + this.done.length; }
  request(dim: number, cx: number, cz: number, prio: number): void {
    const k = `${dim},${cx},${cz}`;
    if (!this.jobs.has(k)) this.jobs.set(k, { dim, cx, cz, prio, n: this.n++, sent: false, fails: 0 });
  }
  cancel(dim: number, cx: number, cz: number): void { this.jobs.delete(`${dim},${cx},${cz}`); }
  /** Called from inside a step, which pays for what happens here: one job is handed over at most. The workers' own
   *  answers, which arrive between frames, hand over the rest. */
  poll(maxJobs: number): GenResult[] {
    if (this.out < this.most) this.feed(this.out + 1);
    return this.done.splice(0, Math.min(maxJobs, this.done.length));
  }
  dispose(): void { this.jobs.clear(); this.done.length = 0; }

  /** Hand the workers the waiting jobs of lowest `prio`, oldest first among equals, until `most` are out. */
  private feed(most: number): void {
    while (this.out < most) {
      let best: Job | null = null, key = '';
      for (const [k, j] of this.jobs) if (!j.sent && (!best || j.prio < best.prio || (j.prio === best.prio && j.n < best.n))) { best = j; key = k; }
      if (!best) return;
      const j = best;
      j.sent = true; this.out++;
      this.pool.urgent({ t: 'gen', cx: j.cx, cz: j.cz, dim: j.dim, seed: this.seed, emit: true }, [], (m) => {
        this.out--;
        // cancelled, or cancelled and asked for again, while it ran
        if (this.jobs.get(key) === j) {
          this.jobs.delete(key);
          if (m) this.done.push({ dim: j.dim, cx: j.cx, cz: j.cz, blocks: m.blocks, biomes: m.biomes, ents: m.ents, hash: m.hash, emit: m.emit });
          // the worker threw: asked twice more, behind the others, then the chunk is left without terrain
          else if (j.fails < 2) this.jobs.set(key, { ...j, n: this.n++, sent: false, fails: j.fails + 1 });
          else console.warn(`chunk ${j.cx},${j.cz} of dimension ${j.dim} could not be generated for the simulation`);
        }
        this.feed(this.most);
      });
    }
  }
}
